{"fingerprint":"49b17662dfce55938167790aede2b2358a34912b3bc4c1306567619efb888568","path":"src/review_gauntlet/cli.py","rule_id":"data-validation","content":"In `_finding_states`, when `finding_ids` is very large, the dynamically constructed `IN (?, ?, ...)` clause could produce an extremely large SQL statement. SQLite has a default limit of 999 bound parameters (SQLITE_MAX_VARIABLE_NUMBER). Passing more finding IDs than this limit would cause a runtime error. Consider batching the query or adding a guard.","suggestion_code":"    results: dict[str, FindingState] = {}
    sorted_ids = sorted(finding_ids)
    batch_size = 900
    for i in range(0, len(sorted_ids), batch_size):
        batch = sorted_ids[i : i + batch_size]
        placeholders = ",".join("?" for _ in batch)
        query = (
            "select finding_id, state from findings "
            f"where session_id = ? and finding_id in ({placeholders})"
        )
        with store.connect() as conn:
            rows = conn.execute(query, (session_id, *batch)).fetchall()
        results.update(
            {str(row["finding_id"]): FindingState(str(row["state"])) for row in rows}
        )
    return results","existing_code":"    placeholders = ",".join("?" for _ in finding_ids)
